class SubprocessExecutor:
    def __init__(self, eval_cmd: list[str] | None = None):
        self.eval_cmd = eval_cmd or ["uv", "run", "python", "-m", "evals"]

    def run_case(self, req: CaseRequest) -> list[RunResult]:
        cmd = [*self.eval_cmd, "run", "--json", "--isolate", "--suite", "all", "--cases", req.case,
               "--repeats", str(req.repeats), "--commit", req.sha, "--run-id", req.run_id]
        if req.baseline:
            cmd += ["--baseline", req.baseline]
        try:
            p = subprocess.run(cmd, cwd=req.workdir, env=req.env, capture_output=True, text=True,
                               timeout=req.timeout)
        except subprocess.TimeoutExpired as e:
            raise EvalInfraError("timeout", f"{req.case} exceeded {req.timeout}s") from e
        try:
            return parse_report(json.loads(_json_tail(p.stdout)))
        except json.JSONDecodeError:
            tail = (p.stderr or p.stdout)[-500:]
            kind = "rate_limit" if RATE_LIMIT_RE.search(tail) else "crash"
            raise EvalInfraError(kind, f"exit {p.returncode}, no JSON report: {tail}")


@dataclass

@contextlib.contextmanager
def worktree(repo: Path, sha: str, root: str | None = None) -> Iterator[Path]:
    """Detached worktree at sha in a temp dir; always removed and pruned, even on error."""
    tmp = Path(tempfile.mkdtemp(prefix="agentbisect-wt-", dir=root))
    path = tmp / "wt"
    try:
        subprocess.run(["git", "-C", str(repo), "worktree", "add", "--detach", str(path), sha],
                       capture_output=True, text=True, check=True)
        yield path
    finally:
        subprocess.run(["git", "-C", str(repo), "worktree", "remove", "--force", str(path)], capture_output=True)
        shutil.rmtree(tmp, ignore_errors=True)
        subprocess.run(["git", "-C", str(repo), "worktree", "prune"], capture_output=True)


def _load_env_file(path: str | None) -> dict[str, str]:

def _unwrap(d: Any) -> Any:
    """CLI envelope is {"data": ..., "success": true}."""
    return d["data"] if isinstance(d, dict) and "data" in d and "success" in d else d


def _text_of(v: Any) -> str | None:
    if v is None:
        return None
    if isinstance(v, str):
        return v
    if isinstance(v, dict):
        for k in ("input", "message", "content", "text", "prompt", "query"):
            if k in v:
                return _text_of(v[k])
        return json.dumps(v, sort_keys=True)
    if isinstance(v, list):
        for m in reversed(v):  # chat messages: last user turn
            if isinstance(m, dict) and m.get("role", "user") == "user":
                return _text_of(m.get("content"))
        return _text_of(v[-1]) if v else None
    return str(v)


def trace_from_dict(d: dict[str, Any]) -> Trace:
    """Tolerant normaliser for CLI list/get items and fixture dicts (camelCase or snake_case)."""
    d = _unwrap(d)
    if isinstance(d.get("trace"), dict):
        d = {**d["trace"], **{k: v for k, v in d.items() if k != "trace"}}
    meta = d.get("metadata") or {}
    tags = d.get("tags") or []
    if isinstance(tags, dict):
        tags = [f"{k}:{v}" for k, v in tags.items()]
    passed = d.get("passed", meta.get("passed"))
    if passed is None:
        res = next((t.split(":", 1)[1] for t in tags if t.startswith("result:")), None)
        passed = {"pass": True, "fail": False}.get(res) if res else None
    return Trace(
        id=str(d.get("traceId") or d.get("trace_id") or d.get("id")),
        workflow=str(d.get("workflowName") or d.get("workflow") or ""),
        status=str(d.get("status") or ""),
        tags=[str(t) for t in tags],
        started_at=str(d.get("startedAt") or d.get("started_at") or ""),
        input=_text_of(d.get("input")),
        metadata=dict(meta),
        passed=passed,
    )
    symbols = list(dict.fromkeys(_HUNK_SYMBOL.findall(hunks))) or git.files_of(sha)
    return stat, symbols, notes


